BEGIN;
ALTER TABLE otp_challenges ADD COLUMN IF NOT EXISTS ip_hash text, ADD COLUMN IF NOT EXISTS device_hash text, ADD COLUMN IF NOT EXISTS provider text, ADD COLUMN IF NOT EXISTS delivery_message_id text, ADD COLUMN IF NOT EXISTS last_attempt_at timestamptz;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS csrf_hash text, ADD COLUMN IF NOT EXISTS device_hash text, ADD COLUMN IF NOT EXISTS ip_hash text, ADD COLUMN IF NOT EXISTS risk text NOT NULL DEFAULT 'normal', ADD COLUMN IF NOT EXISTS rotated_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS last_seen_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS revocation_reason text;
CREATE INDEX IF NOT EXISTS sessions_device_idx ON sessions(user_id,device_hash) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),device_hash text NOT NULL,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),last_ip_hash text,risk text NOT NULL DEFAULT 'normal',UNIQUE(user_id,device_hash));
ALTER TABLE game_versions ADD COLUMN IF NOT EXISTS file_count integer, ADD COLUMN IF NOT EXISTS expanded_bytes bigint, ADD COLUMN IF NOT EXISTS scan_report jsonb, ADD COLUMN IF NOT EXISTS published_by text, ADD COLUMN IF NOT EXISTS published_at timestamptz;
ALTER TABLE games ADD COLUMN IF NOT EXISTS description text, ADD COLUMN IF NOT EXISTS genres text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS icon_url text, ADD COLUMN IF NOT EXISTS banner_url text, ADD COLUMN IF NOT EXISTS min_device_tier text NOT NULL DEFAULT 'lite', ADD COLUMN IF NOT EXISTS rollout_percentage integer NOT NULL DEFAULT 100 CHECK(rollout_percentage BETWEEN 0 AND 100), ADD COLUMN IF NOT EXISTS scheduled_at timestamptz, ADD COLUMN IF NOT EXISTS active_version_id uuid REFERENCES game_versions(id);
CREATE TABLE IF NOT EXISTS game_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),game_id uuid NOT NULL REFERENCES games(id),game_version_id uuid REFERENCES game_versions(id),code text NOT NULL,details text,status text NOT NULL DEFAULT 'open',reported_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
ALTER TABLE payment_transactions ADD COLUMN IF NOT EXISTS paid_at timestamptz, ADD COLUMN IF NOT EXISTS refunded_at timestamptz, ADD COLUMN IF NOT EXISTS refund_reference text, ADD COLUMN IF NOT EXISTS checkout_payload jsonb;
CREATE TABLE IF NOT EXISTS payment_reconciliation_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid REFERENCES payment_transactions(id),reason text NOT NULL,details jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,resolved_by text);
CREATE TABLE IF NOT EXISTS challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,game_ids uuid[] NOT NULL DEFAULT '{}',starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,rules jsonb NOT NULL,reward_policy jsonb NOT NULL,premium_only boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS challenge_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),challenge_id uuid NOT NULL REFERENCES challenges(id),user_id uuid NOT NULL REFERENCES users(id),ledger_id uuid REFERENCES coin_ledger(id),status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(challenge_id,user_id));
CREATE TABLE IF NOT EXISTS score_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),play_session_id uuid NOT NULL REFERENCES play_sessions(id) UNIQUE,user_id uuid NOT NULL REFERENCES users(id),game_id uuid NOT NULL REFERENCES games(id),game_version_id uuid REFERENCES game_versions(id),score bigint NOT NULL,duration_ms integer NOT NULL,status text NOT NULL CHECK(status IN('verified','review','rejected','disqualified')),reasons text[] NOT NULL DEFAULT '{}',completed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS score_events_leaderboard_idx ON score_events(game_id,status,score DESC,duration_ms ASC,completed_at ASC);
CREATE TABLE IF NOT EXISTS tournaments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,game_id uuid NOT NULL REFERENCES games(id),game_version_id uuid REFERENCES game_versions(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,premium_only boolean NOT NULL DEFAULT false,max_entries integer,reward_policy jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tournament_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tournament_id uuid NOT NULL REFERENCES tournaments(id),user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'eligible',joined_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by text,UNIQUE(tournament_id,user_id));
CREATE TABLE IF NOT EXISTS admin_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),amount integer NOT NULL CHECK(amount<>0),reason text NOT NULL,status text NOT NULL,requested_by text NOT NULL,approved_by text,created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,ledger_id uuid REFERENCES coin_ledger(id));
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurred_at timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,action text NOT NULL,target_type text NOT NULL,target_id text,request_id text,metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS audit_target_idx ON audit_events(target_type,target_id,occurred_at DESC);
ALTER TABLE users ADD COLUMN IF NOT EXISTS deletion_requested_at timestamptz, ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
COMMIT;
